sys_script_client.script:
function  onSubmit() {

    var start = g_form.getValue('shift_start');
    var end = g_form.getValue('shift_end');

    if (start == '' || end == '') {
        return;
    }

    var startParts = start.split(':');
    var endParts = end.split(':');

    var startMinutes =
        parseInt(startParts[0], 10) * 60 +
        parseInt(startParts[1], 10);

    var endMinutes =
        parseInt(endParts[0], 10) * 60 +
        parseInt(endParts[1], 10);

    if (endMinutes <= startMinutes) {

        g_form.showErrorBox(
            'shift_end',
            'Shift End must be later than Shift Start.'
        );
          return false;
        g_form.clearValue('shift_end');
    }
}
